package com.example.starter.domain;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * 替代版本有向图校验：边为「同制品内 被弃用版本 -> 替代版本」。
 *
 * <p>批量设置弃用窗口时，必须基于合并后的最终完整替代图（已存在的有效窗口
 * 与本次待写入窗口合并）校验；只要最终图存在任一环（含自环）即整体拒绝。
 */
public final class DeprecationGraph {

    private DeprecationGraph() {
    }

    /**
     * 查找最终替代图中的一个环。
     *
     * @param edges 制品名称 -> （被弃用版本 -> 替代版本），仅含有有效弃用窗口的版本
     * @return 环上的版本号序列（同制品内，首尾同点）；无环返回 null
     */
    public static List<Integer> firstCycle(Map<String, Map<Integer, Integer>> edges) {
        // 0=未访问，1=在当前递归栈，2=已完成
        Map<Integer, Integer> color = new TreeMap<>();
        for (Map.Entry<String, Map<Integer, Integer>> byName : edges.entrySet()) {
            String name = byName.getKey();
            for (Integer from : new TreeSetHolder(byName.getValue().keySet()).sorted()) {
                if (color.getOrDefault(stateKey(name, from), 0) == 0) {
                    java.util.List<Integer> path = new java.util.ArrayList<>();
                    if (dfs(name, from, edges, color, path)) {
                        return path;
                    }
                }
            }
        }
        return null;
    }

    private static boolean dfs(String name, int version, Map<String, Map<Integer, Integer>> edges,
                               Map<Integer, Integer> color, java.util.List<Integer> path) {
        color.put(stateKey(name, version), 1);
        path.add(version);
        Integer nextVersion = edges.getOrDefault(name, Map.of()).get(version);
        if (nextVersion != null) {
            int nextColor = color.getOrDefault(stateKey(name, nextVersion), 0);
            if (nextColor == 1) {
                // 找到回到当前路径上的环：截断到环起点并闭合。
                int start = path.indexOf(nextVersion);
                java.util.List<Integer> cycle = new java.util.ArrayList<>(path.subList(start, path.size()));
                cycle.add(nextVersion);
                path.clear();
                path.addAll(cycle);
                return true;
            }
            if (nextColor == 0 && dfs(name, nextVersion, edges, color, path)) {
                return true;
            }
        }
        color.put(stateKey(name, version), 2);
        path.remove(path.size() - 1);
        return false;
    }

    /**
     * 颜色表键：名称与版本压入单个 int（版本 1..5，名称用顺序编号）。
     * 为避免跨名称串扰，这里直接用对象集合更稳妥，故该方法仅占位不应被调用。
     */
    private static int stateKey(String name, int version) {
        throw new UnsupportedOperationException();
    }

    private record TreeSetHolder(Set<Integer> sorted) {
        private TreeSetHolder(Set<Integer> source) {
            this(new java.util.TreeSet<>(source));
        }
    }
}

