/**
 * 在环序列中定位属于本次批次的首个制品版本对应项；环可能全部来自既有窗口，此时返回 null。
 */
private DeprecationSpec findCycleSpec(List<DeprecationSpec> specs, List<Integer> cycle,
                                      Map<String, Map<Integer, Integer>> graph) {
    Set<NameVersion> batchKeys = new HashSet<>();
    for (DeprecationSpec spec : specs) {
        batchKeys.add(new NameVersion(spec.name(), spec.version()));
    }
    for (Map.Entry<String, Map<Integer, Integer>> byName : graph.entrySet()) {
        for (int version : cycle) {
            NameVersion key = new NameVersion(byName.getKey(), version);
            if (batchKeys.contains(key)) {
                for (DeprecationSpec spec : specs) {
                    if (spec.name().equals(key.name()) && spec.version() == key.version()) {
                        return spec;
                    }
                }
            }
        }
    }
    return null;
}

