    @Test
    void lockBeforeEffectiveSucceedsWithWarningAndFreezesEvidence() {
        service.registerArtifact(requestId(), artifact("app", 1, dep("lib", 1, 2)));
        service.registerArtifact(requestId(), artifact("lib", 1));
