        // 时钟越过生效时刻后重解析（新锁请求）按新时刻裁决：422。
        clock.set(Instant.parse("2026-06-02T00:00:00Z"));
        assertThatThrownBy(() -> service.createLock(requestId(), new LockRequest("app", 1, 4L)))
                .isInstanceOfSatisfying(ApiException.class, e -> {
