                "app", 1, Instant.parse("2026-06-02T00:00:00Z"));
        assertThat(future.blocked()).hasSize(1);
        assertThat(future.warnings()).isEmpty();
        assertThat(repositoryVersion()).isEqualTo(versionBefore);
        assertThat(service.listLocks()).isEmpty();
    }

