                        + "replacement_version, effective_at, note, status, request_id, created_at) "
                        + "VALUES ('lib', 1, 2, CURRENT_TIMESTAMP(6), 'n', 'REGISTERED', 'r2', "
                        + "CURRENT_TIMESTAMP(6))"))
                .isInstanceOf(org.springframework.dao.DuplicateKeyException.class);
    }

