        setWindows(
                window("zlib", 1, 2, "2026-06-01T00:00:00Z", "z"),
                window("alib", 1, 2, "2026-07-01T00:00:00Z", "a"));

        LockFileResponse lock = service.createLock(requestId(), new LockRequest("app", 1, 7L));

        // 警告按名称升序稳定排序。
