                .containsExactly("alib", "zlib");
        Integer rows = jdbcTemplate.queryForObject(
                "SELECT COUNT(1) FROM lock_file_deprecation WHERE lock_file_id = ?",
                Integer.class, lock.id());
        assertThat(rows).isEqualTo(2);
    }
